const BOARD = sheets(SRC).map((p) => relative(SRC, p).replaceAll("\\", "/"))
  .filter((s) => s === "index.css" || (s.startsWith("game/") && !s.startsWith("game/deckbuilder/") && s !== "game/table.css"));
const STEPS = [2, 4, 6, 8, 10, 12, 16, 20, 24, 32, 40];
const MANUAL = new Set([28, 36, 48, 132]);
const PROP = /(?<![\w-])((?:grid-)?(?:row-|column-)?gap|padding(?:-(?:top|right|bottom|left|inline|block)(?:-(?:start|end))?)?|margin(?:-(?:top|right|bottom|left|inline|block)(?:-(?:start|end))?)?|--gap)(\s*:\s*)([^;}]+)/g;
const RAW = /(?<![\w.])(-?)(\d*\.?\d+)(px|rem)\b/g;
const nearest = (px) => { let best = 0; for (const s of STEPS) if (Math.abs(s - px) < Math.abs(best - px)) best = s; return best; };
let changed = 0, manual = 0;
for (const sheet of BOARD) {
